-- TD 1: the twenty reference queries, one per question.
-- Generated by tools/build_verifications.py from reference-td1.csv. Do not edit by hand.
-- Run from the repository root: sqlite3 data/boutique.sqlite < td1/queries-td1.sql
-- It prints the twenty values, C01 to C20, each in euro cents excluding VAT.

-- C01 (period) What is the revenue excluding VAT, in euro cents, of the orders placed from 2026-03-01 00:00:00 to 2026-06-01 00:00:00?
-- written by Marieseka, checked by ines729, value 792800 (published 792800)
SELECT COALESCE(SUM(o.quantity_product * p.price), 0) AS revenue_cents FROM orders o JOIN product p ON p.product_id = o.product_id WHERE o.date >= '2026-03-01 00:00:00' AND o.date < '2026-06-01 00:00:00';

-- C02 (age on a reference date) What is the total revenue excluding VAT, in euro cents, generated by customers who are exactly 25 years old on the reference date 2026-09-25 (all their orders)?
-- written by axel12334556, checked by TasB, value 590320 (published 590320)
SELECT COALESCE(SUM(o.quantity_product * p.price), 0) AS revenue_cents FROM orders o JOIN product p ON p.product_id = o.product_id JOIN customers c ON c.customer_id = o.customer_id WHERE (CAST(substr('2026-09-25', 1, 4) AS INTEGER) - CAST(substr(c.birth_date, 1, 4) AS INTEGER) - (substr('2026-09-25', 6, 5) < substr(c.birth_date, 6, 5))) = 25;

